index a348a9c74..3c28fe43c 100644
--- a/pkg/sentry/pgalloc/pgalloc_test.go
+++ b/pkg/sentry/pgalloc/pgalloc_test.go
@@ -167,6 +167,128 @@ func TestAllocateAndCommit(t *testing.T) {
